module trek_planner (input clk, input rst_n, input start, input [3:0] node_count, input [3:0] edge_count, input [5:0] edge_u, input [5:0] edge_v, input [5:0] edge_weight, input edge_valid, input compute_start, output reg [7:0] wait_time, output reg done, output reg error); reg [2:0] state; reg [15:0] edge_u_arr [15:0]; reg [15:0] edge_v_arr [15:0]; reg [5:0] edge_weight_arr [15:0]; reg [3:0] edge_count_reg; reg [3:0] reg_node_count; reg [3:0] reg_edge_count; localparam DIST_INF = 256; reg [7:0] distance [0:15]; reg [15:0] processed; reg [3:0] dijkstra_iter; reg [7:0] knight_total; reg [7:0] day_total; reg [7:0] wait_time_reg; reg done_reg; reg error_reg; always @(negedge rst_n) begin if (!rst_n) begin state <= 3'b000; edge_count_reg <= 4'd0; reg_node_count <= 4'd0; reg_edge_count <= 4'd0; dijkstra_iter <= 4'd0; done_reg <= 1'b0; error_reg <= 1'b0; wait_time_reg <= 8'd0; processed <= 16'd0; distance[0] <= 8'd0; distance[1] <= DIST_INF; distance[2] <= DIST_INF; distance[3] <= DIST_INF; distance[4] <= DIST_INF; distance[5] <= DIST_INF; distance[6] <= DIST_INF; distance[7] <= DIST_INF; distance[8] <= DIST_INF; distance[9] <= DIST_INF; distance[10] <= DIST_INF; distance[11] <= DIST_INF; distance[12] <= DIST_INF; distance[13] <= DIST_INF; distance[14] <= DIST_INF; distance[15] <= DIST_INF; end end always @(posedge clk) begin if (!rst_n) begin end else begin case (state) 3'b000: if (compute_start) begin state <= 3'b001; reg_node_count <= node_count; reg_edge_count <= edge_count; edge_count_reg <= 4'd0; end end 3'b001: if (edge_valid) begin edge_u_arr[edge_count_reg] <= edge_u; edge_v_arr[edge_count_reg] <= edge_v; edge_weight_arr[edge_count_reg] <= edge_weight; edge_count_reg <= edge_count_reg + 1; if (edge_count_reg == reg_edge_count) begin state <= 3'b010; end end end 3'b010: if (dijkstra_iter < reg_node_count) begin dijkstra_iter <= dijkstra_iter + 1; end else begin if (distance[reg_node_count-1] >= DIST_INF) begin error_reg <= 1'b1; end else begin knight_total <= distance[reg_node_count-1]; state <= 3'b100; end end end 3'b100: if (knight_total < DIST_INF) begin day_total <= ((knight_total + 11) / 12) * 12; wait_time_reg <= day_total - knight_total; end else begin wait_time_reg <= 8'd0; end state <= 3'b110; end end 3'b110: done_reg <= 1'b1; endcase end end end assign wait_time = wait_time_reg; assign done = done_reg; assign error = error_reg; endmodule